arguments.command:
cd /workspace/submission && python3 - <<'EOF'
import os,stat
total=0;files=[];dirs=0;bad=[]
for root,ds,fs in os.walk('.'):
 dirs+=len(ds)
 for f in fs:
  p=os.path.join(root,f);st=os.lstat(p);total+=st.st_size
  files.append((p,st.st_size,st.st_nlink,stat.S_ISREG(st.st_mode)))
  if not stat.S_ISREG(st.st_mode) or st.st_nlink!=1:bad.append(p)
print('files',len(files),'dirs',dirs,'entries',len(files)+dirs,'bytes',total,'bad',bad)
for p,s,n,r in sorted(files):print(p,s)
EOF
